      const { rows: [row] } = await client.query("SELECT * FROM sbu_chat_quota WHERE user_id=$1 FOR UPDATE", [userId]);
      const { rows: [clock] } = await client.query("SELECT clock_timestamp() AS now");
      const now = new Date(clock.now).getTime();
      const day = Math.floor(now / 864e5) * 864e5;
      const minute = Math.floor(now / 6e4) * 6e4;
      let dayCount = new Date(row.day_start).getTime() === day ? row.day_count : 0;
      let minuteCount = new Date(row.minute_start).getTime() === minute ? row.minute_count : 0;
      let activeId = row.lease_id;
      let activeUntil = row.lease_until ? new Date(row.lease_until).getTime() : 0;
      if (activeUntil <= now || operation === "finish" && activeId === leaseId) {
        activeId = null;
        activeUntil = 0;
      }
      let code;
      let reserved;
      if (operation === "reserve") {
        if (dayCount >= dailyLimit) code = "chat_daily_limit";
        else if (activeId) code = "chat_busy";
        else if (minuteCount >= 6) code = "chat_minute_limit";
        else {
          dayCount++;
          minuteCount++;
          reserved = activeId = randomUUID3();
          activeUntil = now + 12e4;
        }
      }
      await client.query(
        `UPDATE sbu_chat_quota SET day_start=$2, day_count=$3,
        minute_start=$4, minute_count=$5, lease_id=$6, lease_until=$7 WHERE user_id=$1`,
        [userId, new Date(day), dayCount, new Date(minute), minuteCount, activeId, activeUntil ? new Date(activeUntil) : null]
      );
      const blockedUntil = Math.max(
        dayCount >= dailyLimit ? day + 864e5 : 0,
        minuteCount >= 6 ? minute + 6e4 : 0,
        activeUntil
      );
      const quota = {
        userId,
        dailyLimit,
        dailyRemaining: Math.max(0, dailyLimit - dayCount),
        dailyResetAt: new Date(day + 864e5),
        minuteLimit: 6,
        minuteRemaining: Math.max(0, 6 - minuteCount),
        minuteResetAt: new Date(minute + 6e4),
        busy: !!activeId,
        retryAfterSeconds: Math.max(0, Math.ceil((blockedUntil - now) / 1e3))
      };
      await client.query("COMMIT");
